switch_helix() {
  mkdir -p "$HOME/.config/helix/themes"
  cat > "$HOME/.config/helix/themes/switch-theme.toml" << EOF
# ${C[name]} — auto-generated by switch-theme.sh
"ui.background.separator" = { fg = "${C[surface0]}" }
"ui.cursor" = { modifiers = ["reversed"] }
"ui.cursor.insert" = { modifiers = ["underlined"] }
"ui.cursor.select" = { modifiers = ["reversed"] }
"ui.cursor.match" = { fg = "${C[yellow]}", modifiers = ["underlined"] }
"ui.cursor.primary" = { modifiers = ["reversed"] }
"ui.gutter" = { bg = "${C[base]}" }
"ui.gutter.selected" = { fg = "${C[text]}", bg = "${C[surface0]}", modifiers = ["bold"] }
"ui.linenr" = { fg = "${C[overlay1]}" }
"ui.linenr.selected" = { fg = "${C[text]}", bg = "${C[surface0]}" }
"ui.selection" = { bg = "${C[surface1]}" }
"ui.selection.primary" = { bg = "${C[blue]}", fg = "${C[base]}" }
"ui.statusline" = { fg = "${C[text]}", bg = "${C[surface0]}" }
"ui.statusline.inactive" = { fg = "${C[overlay1]}", bg = "${C[base]}" }
"ui.statusline.normal" = { fg = "${C[base]}", bg = "${C[blue]}" }
"ui.statusline.insert" = { fg = "${C[base]}", bg = "${C[green]}" }
"ui.statusline.select" = { fg = "${C[base]}", bg = "${C[mauve]}" }
"ui.popup" = { fg = "${C[text]}", bg = "${C[surface0]}" }
"ui.popup.info" = { fg = "${C[text]}", bg = "${C[surface1]}" }
"ui.window" = { bg = "${C[surface0]}" }
"ui.help" = { fg = "${C[text]}", bg = "${C[surface0]}" }
"ui.text" = { fg = "${C[text]}" }
"ui.text.focus" = { fg = "${C[text]}", modifiers = ["bold"] }
"ui.text.info" = { fg = "${C[blue]}" }
"ui.virtual.ruler" = { bg = "${C[surface0]}" }
"ui.virtual.whitespace" = { fg = "${C[overlay1]}" }
"ui.virtual.indent-guide" = { fg = "${C[overlay0]}" }
"ui.virtual.wrap" = { fg = "${C[overlay1]}" }
"ui.menu" = { fg = "${C[text]}", bg = "${C[surface0]}" }
"ui.menu.selected" = { fg = "${C[base]}", bg = "${C[blue]}", modifiers = ["bold"] }
"ui.menu.scroll" = { fg = "${C[overlay1]}" }
"warning" = { fg = "${C[yellow]}" }
"error" = { fg = "${C[red]}" }
"info" = { fg = "${C[blue]}" }
"hint" = { fg = "${C[teal]}" }
"diagnostic" = { modifiers = ["underlined"] }
"diagnostic.hint" = { underline = { color = "${C[teal]}", style = "dashed" } }
"diagnostic.info" = { underline = { color = "${C[blue]}", style = "dashed" } }
"diagnostic.warning" = { underline = { color = "${C[yellow]}", style = "curl" } }
"diagnostic.error" = { underline = { color = "${C[red]}", style = "curl" } }
"variable" = { fg = "${C[text]}" }
"variable.builtin" = { fg = "${C[orange]}" }
"variable.other.member" = { fg = "${C[red]}" }
"function" = { fg = "${C[blue]}" }
"function.builtin" = { fg = "${C[blue]}" }
"function.macro" = { fg = "${C[teal]}" }
"keyword" = { fg = "${C[mauve]}" }
"operator" = { fg = "${C[teal]}" }
"comment" = { fg = "${C[overlay1]}" }
"special" = { fg = "${C[teal]}" }
"string" = { fg = "${C[green]}" }
"string.special" = { fg = "${C[teal]}" }
"constant" = { fg = "${C[orange]}" }
"constant.character.escape" = { fg = "${C[teal]}" }
"type" = { fg = "${C[yellow]}" }
"constructor" = { fg = "${C[blue]}" }
"namespace" = { fg = "${C[blue]}" }
"label" = { fg = "${C[mauve]}" }
"tag" = { fg = "${C[blue]}" }
"attribute" = { fg = "${C[yellow]}" }
"diff.plus" = { fg = "${C[green]}" }
"diff.minus" = { fg = "${C[red]}" }
"diff.delta" = { fg = "${C[yellow]}" }
EOF
  pkill -USR1 -u "$USER" -x hx 2>/dev/null || true
}
